#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. One-time Azure setup (docs/infrastructure.md).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Helpers for this wizard (the library above stays untouched).

require_tool() {
  command -v "$1" >/dev/null 2>&1 || { warn "$1 is not installed: $2"; exit 1; }
}

# setup_env ENV: Entra admin group, subscription-level bootstrap, optional
# sign-in apps, then the GitHub variables the workflows read for that
# environment.
setup_env() {
  local env="$1" upper sub_var sub tier_var tier budget_var group group_id me outputs client_id principal_id
  upper=$(printf '%s' "$env" | tr '[:lower:]' '[:upper:]')
  sub_var="${upper}_AZURE_SUBSCRIPTION_ID"; sub="${!sub_var}"
  tier_var="${upper}_TIER"; tier="${!tier_var}"
  budget_var="${upper}_BUDGET_AMOUNT"
  group="grp-${APP_NAME}-${env}-sql-admins"

  say "Entra ID group $group administers the $env SQL server."
  group_id=$(az ad group list --display-name "$group" --query "[0].id" --output tsv)
  if [[ -z "$group_id" ]]; then
    group_id=$(az ad group create --display-name "$group" --mail-nickname "$group" --query id --output tsv)
    printf '  %s✓ created%s group %s\n' "$GREEN" "$RESET" "$group"
  else
    note "group $group already exists"
  fi
  me=$(az ad signed-in-user show --query id --output tsv)
  if [[ "$(az ad group member check --group "$group_id" --member-id "$me" --query value --output tsv)" != "true" ]]; then
    az ad group member add --group "$group_id" --member-id "$me"
    printf '  %s✓ added%s you to %s\n' "$GREEN" "$RESET" "$group"
  fi

  say ""
  say "Next: deploy infra/bootstrap/main.bicep to subscription $sub ($tier tier). It creates"
  say "rg-${APP_NAME}-${env}-${REGION_CODE}, the pipeline's deploy identity, the allowed-types and"
  say "allowed-locations policies, and a budget of ${!budget_var} alerting $BUDGET_EMAIL."
  confirm "Deploy the $env bootstrap now?" || { SKIPPED+=("$env bootstrap (re-run this wizard)"); return 0; }
  export APP_NAME REGION REGION_CODE
  # Set EXTRA_ALLOWED_LOCATIONS (e.g. europe) before running for an External ID tenant.
  export EXTRA_ALLOWED_LOCATIONS="${EXTRA_ALLOWED_LOCATIONS:-}"
  outputs=$(TIER="$tier" \
    GITHUB_OIDC_REPO="$GITHUB_OIDC_REPO" BUDGET_EMAIL="$BUDGET_EMAIL" BUDGET_AMOUNT="${!budget_var}" \
    az deployment sub create \
    --subscription "$sub" --location "$REGION" --name "${APP_NAME}-bootstrap-$env" \
    --parameters "infra/bootstrap/$env.bicepparam" \
    --query properties.outputs --output json)
  client_id=$(jq -r .deployClientId.value <<<"$outputs")
  principal_id=$(jq -r .deployPrincipalId.value <<<"$outputs")
  printf '  %s✓ deployed%s bootstrap for %s\n' "$GREEN" "$RESET" "$env"

  if [[ "$(az ad group member check --group "$group_id" --member-id "$principal_id" --query value --output tsv)" != "true" ]]; then
    # A brand-new identity can take a moment to appear in Entra ID.
    for _ in 1 2 3 4 5 6; do
      az ad group member add --group "$group_id" --member-id "$principal_id" 2>/dev/null && break
      sleep 10
    done
    printf '  %s✓ added%s the deploy identity to %s\n' "$GREEN" "$RESET" "$group"
  fi

  write_env "${upper}_AZURE_CLIENT_ID" "$client_id"
  write_env "${upper}_SQL_ADMIN_GROUP_NAME" "$group"
  write_env "${upper}_SQL_ADMIN_GROUP_ID" "$group_id"
  set_var "${upper}_AZURE_SUBSCRIPTION_ID" "$sub"
  set_var "${upper}_AZURE_CLIENT_ID" "$client_id"
  set_var "${upper}_SQL_ADMIN_GROUP_NAME" "$group"
  set_var "${upper}_SQL_ADMIN_GROUP_ID" "$group_id"
  set_var "${upper}_TIER" "$tier"
  pause

  local host="app-${APP_NAME}-${env}-${REGION_CODE}.azurewebsites.net"

  # "Sign in with Microsoft": any work, school or personal account. Optional.
  if confirm "Turn on \"Sign in with Microsoft\" for $env?"; then
    local ms_app="${APP_NAME}-${env}-signin" ms_client_id
    ms_client_id=$(az ad app list --display-name "$ms_app" --query "[0].appId" --output tsv)
    if [[ -z "$ms_client_id" ]]; then
      ms_client_id=$(az ad app create --display-name "$ms_app" \
        --sign-in-audience AzureADandPersonalMicrosoftAccount \
        --web-redirect-uris "https://$host/.auth/login/aad/callback" \
        --enable-id-token-issuance true --query appId --output tsv)
      printf '  %s✓ created%s app registration %s\n' "$GREEN" "$RESET" "$ms_app"
    fi
    write_env "${upper}_MICROSOFT_AUTH_CLIENT_ID" "$ms_client_id"
    set_var "${upper}_MICROSOFT_AUTH_CLIENT_ID" "$ms_client_id"
  fi

  # "Sign in with GitHub" needs an OAuth app; GitHub has no API to create one.
  if confirm "Turn on \"Sign in with GitHub\" for $env?"; then
    open_url "https://github.com/settings/applications/new"
    step "Application name: ${APP_NAME} $env"
    step "Homepage URL: https://$host"
    step "Authorization callback URL: https://$host/.auth/login/github/callback"
    step "Register it, then click 'Generate a new client secret'."
    local id_key="${upper}_GITHUB_AUTH_CLIENT_ID" secret_key="${upper}_GITHUB_AUTH_CLIENT_SECRET"
    ask "$id_key" "Paste the Client ID:"
    write_env "$id_key" "${!id_key}"
    set_var "$id_key" "${!id_key}"
    ask_secret "$secret_key" "Paste the client secret:"
    set_secret "$secret_key" "${!secret_key}"
  fi
  note "Sign in with email (Entra External ID) is set up by hand: see docs/infrastructure.md."
  pause
}

ask_tier() {
  local key="$1" env="$2"
  while :; do
    ask "$key" "Tier for $env (free or paid):"
    [[ "${!key}" == free || "${!key}" == paid ]] && break
    warn "type free or paid"
  done
  write_env "$key" "${!key}"
}

run_wizard() {

TOTAL_STAGES=7

cd "$(dirname "$0")/.."

banner "One-time Azure setup"

stage "Tools, names and tiers"
say "This wizard needs the Azure CLI, the GitHub CLI and jq, signed in as an"
say "Owner of the Azure tenant and an admin of the GitHub repository."
require_tool az "https://learn.microsoft.com/cli/azure/install-azure-cli"
require_tool gh "https://cli.github.com"
require_tool jq "https://jqlang.org/download/"
az account show >/dev/null 2>&1 || az login
gh auth status >/dev/null 2>&1 || gh auth login
write_env AZURE_TENANT_ID "$(az account show --query tenantId --output tsv)"
write_env GITHUB_REPO "$(gh repo view --json nameWithOwner --jq .nameWithOwner)"
# GitHub's OIDC tokens name the repo with numeric IDs: owner@id/repo@id.
write_env GITHUB_OIDC_REPO "$(gh api "repos/$GITHUB_REPO" --jq '"\(.owner.login)@\(.owner.id)/\(.name)@\(.id)"')"
while :; do
  ask APP_NAME "Short app name, lowercase letters and digits, 2-12 characters (used in every resource name):"
  [[ "$APP_NAME" =~ ^[a-z][a-z0-9]{1,11}$ ]] && break
  warn "use 2-12 lowercase letters and digits, starting with a letter"
done
write_env APP_NAME "$APP_NAME"
ask REGION "Azure region [swedencentral has the free App Service plan]:"
REGION="${REGION:-swedencentral}"; write_env REGION "$REGION"
ask REGION_CODE "Short region code for names [sdc]:"
REGION_CODE="${REGION_CODE:-sdc}"; write_env REGION_CODE "$REGION_CODE"
note "free: only services that cannot charge (F1 plan, free SQL offer, budget alert at 1)."
note "paid: B1 plan with Always On, a SQL database that never pauses, Application Insights."
ask_tier DEV_TIER dev
ask_tier PROD_TIER prod
for e in DEV PROD; do
  tier_var="${e}_TIER"; amount_var="${e}_BUDGET_AMOUNT"
  if [[ "${!tier_var}" == free ]]; then
    write_env "$amount_var" 1
  else
    ask "$amount_var" "Monthly budget for $(tr '[:upper:]' '[:lower:]' <<<"$e") in your billing currency (e.g. 30):"
    write_env "$amount_var" "${!amount_var}"
  fi
done
ask BUDGET_EMAIL "Email address for budget alerts:"
write_env BUDGET_EMAIL "$BUDGET_EMAIL"
pause

stage "Create the dev and prod subscriptions"
say "Both must be pay-as-you-go subscriptions. A free-trial account has to be"
say "upgraded to pay-as-you-go first, or it switches off after 30 days."
open_url "https://portal.azure.com/#view/Microsoft_Azure_Billing/SubscriptionsBladeV2"
step "Create a subscription named ${APP_NAME}-dev, then one named ${APP_NAME}-prod (Subscriptions → + Add)."
step "Wait until both show as Active."
pause "Press Enter when both exist"
az account list --refresh --query "[].{name:name, id:id, state:state}" --output table
ask DEV_AZURE_SUBSCRIPTION_ID "Subscription ID of ${APP_NAME}-dev:"
write_env DEV_AZURE_SUBSCRIPTION_ID "$DEV_AZURE_SUBSCRIPTION_ID"
ask PROD_AZURE_SUBSCRIPTION_ID "Subscription ID of ${APP_NAME}-prod:"
write_env PROD_AZURE_SUBSCRIPTION_ID "$PROD_AZURE_SUBSCRIPTION_ID"
pause

stage "Register resource providers"
say "New subscriptions must register each Azure service before first use."
for sub in "$DEV_AZURE_SUBSCRIPTION_ID" "$PROD_AZURE_SUBSCRIPTION_ID"; do
  for ns in Microsoft.Web Microsoft.Sql Microsoft.ManagedIdentity Microsoft.Consumption Microsoft.Insights Microsoft.OperationalInsights; do
    az provider register --subscription "$sub" --namespace "$ns" --wait
    printf '  %s✓%s %s in %s\n' "$GREEN" "$RESET" "$ns" "$sub"
  done
done
pause

stage "Set up dev"
setup_env dev

stage "Set up prod"
setup_env prod

stage "GitHub settings"
set_var AZURE_TENANT_ID "$AZURE_TENANT_ID"
set_var APP_NAME "$APP_NAME"
set_var REGION_CODE "$REGION_CODE"
say "The workflows now have everything they need. No Azure secret is stored in"
say "GitHub: they sign in to Azure with OIDC. The only GitHub secrets are the"
say "OAuth apps' client secrets."
pause

stage "First deployments"
if confirm "Start the first dev deployment now?"; then
  gh workflow run dev.yml --ref main && open_url "https://github.com/$GITHUB_REPO/actions/workflows/dev.yml"
fi
say ""
say "For prod, run:  scripts/release.sh v0.1.0"
say "When the prod workflow is green, come back here to switch on the hourly health check."
if confirm "Is prod deployed?"; then
  set_var PROD_URL "https://app-${APP_NAME}-prod-${REGION_CODE}.azurewebsites.net"
else
  SKIPPED+=("GitHub variable PROD_URL (re-run this wizard after the first prod release)")
fi
pause

finish
}

run_wizard "$@"; exit
